#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

PROTO Logger [
  initializeOnly SFInt32 level 2
  outputOnly     SFInt32 result
]
{
  DEF Log Script {
    initializeOnly SFInt32 level IS level
    outputOnly     SFInt32 result IS result

    url "javascript:
function initialize () { result = level * 10; print ('logger initialize ' + level); }
"
  }
}

#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

PROTO Other [
  initializeOnly SFFloat size 9
]
{
  Transform {
    children Shape {
      geometry Box {
        size 1 1 1
      }
    }
  }
}

PROTO Thing [
  initializeOnly SFFloat size 7
]
{
  Transform {
    children Shape {
      geometry Sphere {
        radius IS size
      }
    }
  }
}

#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

PROTO Widget [
  initializeOnly SFFloat  size 5
  initializeOnly SFColor  color 0 0 1
  initializeOnly MFString label "default"
  inputOutput    SFVec3f  offset 0 0 0
]
{
  Transform {
    translation IS offset
    children Shape {
      appearance Appearance {
        material Material {
          diffuseColor IS color
        }
      }
      geometry Sphere {
        radius IS size
      }
    }
  }
}
